"""Stable UI error protocol for Pond settings helpers."""
ERROR_CODES = {'No connected displays': 'pond.no_connected_displays', 'Invalid display coordinates': 'pond.invalid_display_coordinates', 'Invalid display size': 'pond.invalid_display_size', 'Displays cannot overlap': 'pond.displays_cannot_overlap', 'Display edges must touch so the cursor can move between them': 'pond.display_edges_must_touch_so_the_cursor_can_move_between_them', 'Multiple matching output blocks; consolidate them before changing this display': 'pond.multiple_matching_output_blocks_consolidate_them_before_changing_this_display', 'Display disconnected before the change was applied': 'pond.display_disconnected_before_the_change_was_applied', 'The compositor did not accept the requested display settings': 'pond.the_compositor_did_not_accept_the_requested_display_settings', 'Displays changed. Reopen Arrange and try again.': 'pond.displays_changed_reopen_arrange_and_try_again', 'Display is no longer connected': 'pond.display_is_no_longer_connected', 'The selected display changed. Please select it again.': 'pond.the_selected_display_changed_please_select_it_again', 'Unsupported display scale': 'pond.unsupported_display_scale', 'This display does not advertise that mode': 'pond.this_display_does_not_advertise_that_mode', 'Adaptive sync is unavailable on this display': 'pond.adaptive_sync_is_unavailable_on_this_display', 'Unknown display action': 'pond.unknown_display_action', 'Displays changed. Please try again.': 'pond.displays_changed_please_try_again', 'Display configuration changed elsewhere. Please try again.': 'pond.display_configuration_changed_elsewhere_please_try_again', 'Brightness control is unavailable for this display': 'pond.brightness_control_is_unavailable_for_this_display', 'Choose a readable image file': 'pond.choose_a_readable_image_file', 'Unknown wallpaper mode': 'pond.unknown_wallpaper_mode', 'Unknown theme': 'pond.unknown_theme', 'Niri did not apply the keyboard languages': 'pond.niri_did_not_apply_the_keyboard_languages', 'Unknown keyboard language': 'pond.unknown_keyboard_language', 'Keep at least one keyboard language': 'pond.keep_at_least_one_keyboard_language', 'Could not change Bluetooth settings': 'pond.could_not_change_bluetooth_settings', 'Could not restore the previous display configuration': 'pond.could_not_restore_the_previous_display_configuration', 'Could not read system settings': 'pond.could_not_read_system_settings', 'Could not apply display settings': 'pond.could_not_apply_display_settings', 'Could not apply appearance settings': 'pond.could_not_apply_appearance_settings'}


def error_payload(error, fallback):
    detail = str(error)
    if '; could not fully restore displays:' in detail:
        return {'error': ERROR_CODES['Could not restore the previous display configuration'], 'errorParameters': [], 'detail': detail}
    for prefix, code in [('Duplicate display setting: ', 'pond.duplicate_display_setting_1'), ('Unknown keyboard language: ', 'pond.unknown_keyboard_language_1')]:
        if detail.startswith(prefix):
            return {'error': code, 'errorParameters': [detail[len(prefix):]], 'detail': detail}
    return {'error': ERROR_CODES.get(detail, ERROR_CODES[fallback]), 'errorParameters': [], 'detail': detail}
